The counter goes into the status object so React sees a new child. The counter is rendered as a visually hidden prefix that screen readers read but sighted users don't see. This makes the DOM text change on every announce, which triggers a fresh reading.

```jsx
// PlantsList.jsx
import { useEffect, useRef, useState } from 'react';
import { loadPlants, deletePlant, clearPlants } from './storage';

// Insert or replace by id (string/number tolerant).
const upsert = (list, plant) => {
  const i = list.findIndex((p) => String(p.id) === String(plant.id));
  if (i < 0) return [...list, plant];
  const next = list.slice();
  next[i] = plant;
  return next;
};

let announceCounter = 0;

export default function PlantsList({ savedPlant = null, onPlantSaved, onPlantsChange }) {
  const [plants, setPlants] = useState([]);
  // status is { text, key } or null. key increments on every announce so React
  // always sees a new element, even when the text is repeated.
  const [status, setStatus] = useState(null);
  const [confirmingId, setConfirmingId] = useState(null); // id awaiting delete confirmation
  const confirmRef = useRef(null);
  const clearRef = useRef(null);
  const containerRef = useRef(null);       // final focus fallback when the list becomes empty
  const deleteBtnRefs = useRef(new Map()); // id -> that row's Delete button
  const restoreIdRef = useRef(null);       // row to return focus to when a prompt closes

  // Latest list and callbacks, readable from effects and handlers without re-running them.
  const plantsRef = useRef([]);
  const callbacksRef = useRef({ onPlantSaved, onPlantsChange });
  useEffect(() => {
    callbacksRef.current = { onPlantSaved, onPlantsChange };
  });

  // Single place that updates the list, the ref, and the parent's onPlantsChange.
  const commit = (next) => {
    plantsRef.current = next;
    setPlants(next);
    callbacksRef.current.onPlantsChange?.(next);
  };

  const announce = (text) => setStatus({ text, key: ++announceCounter });

  // Load on mount.
  useEffect(() => {
    let cancelled = false;
    loadPlants()
      .then((list) => {
        if (cancelled) return;
        plantsRef.current = list;
        setPlants(list);
      })
      .catch((err) => { if (!cancelled) announce(err.message); });
    return () => { cancelled = true; };
  }, []);

  // Upsert the incoming saved plant, then notify both callbacks.
  useEffect(() => {
    if (!savedPlant) return;
    commit(upsert(plantsRef.current, savedPlant));
    callbacksRef.current.onPlantSaved?.(savedPlant);
  }, [savedPlant]);

  // Status auto-clears after 3s. Each new status object restarts the timer; unmount cancels it.
  useEffect(() => {
    if (!status) return;
    const timer = setTimeout(() => setStatus(null), 3000);
    return () => clearTimeout(timer);
  }, [status]);

  // Prompt focus management: focus Confirm when opened; Escape cancels;
  // when closed, return focus to the row's Delete button if it still exists.
  useEffect(() => {
    if (confirmingId !== null) {
      confirmRef.current?.focus();
      const onKey = (e) => {
        if (e.key === 'Escape') closePrompt();
      };
      document.addEventListener('keydown', onKey);
      return () => document.removeEventListener('keydown', onKey);
    }
    const id = restoreIdRef.current;
    if (id !== null) {
      restoreIdRef.current = null;
      deleteBtnRefs.current.get(id)?.focus();
    }
  }, [confirmingId]);

  // Close the prompt. Focus goes back to that row's Delete button.
  const closePrompt = () => {
    restoreIdRef.current = confirmingId;
    setConfirmingId(null);
  };

  const handleDelete = async (id) => {
    restoreIdRef.current = null; // the row is about to be removed, so don't restore to it
    setConfirmingId(null);
    setStatus(null);

    // Pick the focus target and the plant's name from the current list before removal.
    const list = plantsRef.current;
    const idx = list.findIndex((p) => String(p.id) === String(id));
    const deleted = list[idx];
    const neighbor = list[idx + 1] ?? list[idx - 1] ?? null;

    try {
      const next = await deletePlant(id);
      if (next !== null) {
        commit(next); // null = not found; leave state alone
        if (deleted) announce(`Deleted: ${deleted.name}`);
        const target = neighbor ? deleteBtnRefs.current.get(neighbor.id) : null;
        // Fallbacks: Clear All if rows remain (it's enabled), otherwise the container.
        (target ?? (next.length > 0 ? clearRef.current : containerRef.current))?.focus();
      }
    } catch (err) {
      announce(err.message);
    }
  };

  const handleClear = async () => {
    restoreIdRef.current = null;
    setStatus(null);
    setConfirmingId(null);
    try {
      commit(await clearPlants());
      containerRef.current?.focus(); // list is now empty; Clear All is disabled
    } catch (err) {
      announce(err.message);
    }
  };

  return (
    <div ref={containerRef} tabIndex={-1}>
      <button ref={clearRef} type="button" onClick={handleClear} disabled={plants.length === 0}>
        Clear All
      </button>

      {status && (
        <p key={status.key} role="status" aria-live="assertive" aria-atomic="true">
          {status.text}
        </p>
      )}

      <ul>
        {plants.map((p) => (
          <li key={p.id}>
            <strong>{p.name}</strong> — every {p.intervalDays} days{' '}
            {confirmingId === p.id ? (
              <span role="group" aria-label={`Confirm delete ${p.name}`}>
                Delete this plant?{' '}
                <button
                  ref={confirmRef}
                  type="button"
                  onClick={() => handleDelete(p.id)}
                >
                  Confirm
                </button>{' '}
                <button type="button" onClick={closePrompt}>
                  Cancel
                </button>
              </span>
            ) : (
              <button
                type="button"
                ref={(el) => {
                  if (el) deleteBtnRefs.current.set(p.id, el);
                  else deleteBtnRefs.current.delete(p.id);
                }}
                onClick={() => setConfirmingId(p.id)}
              >
                Delete
              </button>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}
```

Notes:
- The `key` on the `<p>` forces React to unmount the old paragraph and mount a new one. The screen reader sees a new element in the live region and announces it, even when the text is identical.
- `announceCounter` is a module-level variable. It never resets, which is fine. It just needs to be unique per announce call.
- No visually hidden counter text is needed. The `key` swap alone is enough to trigger a fresh announcement, since the live region's content changes from the screen reader's perspective (old element removed, new element inserted
